create table if not exists private.player_art_profiles(user_id uuid not null references auth.users(id) on delete cascade,channel text not null check(channel in('formal','test')),arts_capacity integer not null default 8 check(arts_capacity between 8 and 40),legacy_imported boolean not null default false,revision bigint not null default 1,updated_at timestamptz not null default now(),primary key(user_id,channel));
create table if not exists private.player_sect_arts(user_id uuid not null references auth.users(id) on delete cascade,channel text not null check(channel in('formal','test')),sect_name text not null,sect_star integer not null check(sect_star between 1 and 9),slot integer not null check(slot between 0 and 2),level integer not null default 1 check(level between 1 and 10),learned_at timestamptz not null default now(),primary key(user_id,channel,sect_name,slot));
alter table private.player_art_profiles enable row level security;alter table private.player_sect_arts enable row level security;revoke all on private.player_art_profiles,private.player_sect_arts from public,anon,authenticated;
create or replace function private.sect_slot_is_skill(p_sect text,p_slot integer) returns boolean language sql immutable set search_path='' as $$select p_slot=2 and p_sect=any(array['斷刃堂','御風門','鎮岳宗','焚心魔教','幽冥血海','萬壽仙山','蒼穹道統','燭龍神庭','諸天星羅神宗'])$$;
create or replace function private.sect_arts_snapshot(p_user uuid,p_channel text) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('revision',coalesce((select revision from private.player_art_profiles where user_id=p_user and channel=p_channel),0),'capacity',coalesce((select arts_capacity from private.player_art_profiles where user_id=p_user and channel=p_channel),8),'arts',coalesce((select jsonb_agg(jsonb_build_object('sect',sect_name,'star',sect_star,'slot',slot,'level',level) order by learned_at) from private.player_sect_arts where user_id=p_user and channel=p_channel),'[]'::jsonb))$$;

create or replace function public.player_sect_arts_bootstrap(p_channel text,p_legacy_arts jsonb,p_legacy_capacity integer) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());profile private.player_art_profiles;x jsonb;c record;sect_name text;slot_value integer;level_value integer;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') or jsonb_typeof(coalesce(p_legacy_arts,'[]'))<>'array' or jsonb_array_length(coalesce(p_legacy_arts,'[]'))>500 then raise exception '門派功法資料不正確';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-sect-arts-'||p_channel));insert into private.player_art_profiles(user_id,channel) values(uid,p_channel) on conflict do nothing;select * into profile from private.player_art_profiles where user_id=uid and channel=p_channel for update;if not profile.legacy_imported then update private.player_art_profiles set arts_capacity=least(40,greatest(8,coalesce(p_legacy_capacity,8))),legacy_imported=true,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into profile;for x in select value from jsonb_array_elements(coalesce(p_legacy_arts,'[]')) loop sect_name:=coalesce(x->>'sourceSect',x->>'sect');slot_value:=coalesce((x->>'slot')::integer,-1);level_value:=least(10,greatest(1,coalesce((x->>'level')::integer,1)));select * into c from private.sect_catalog() where name=sect_name;if c.name is not null and slot_value between 0 and 2 then insert into private.player_sect_arts(user_id,channel,sect_name,sect_star,slot,level) values(uid,p_channel,c.name,c.star,slot_value,case when private.sect_slot_is_skill(c.name,slot_value) then 1 else level_value end) on conflict do nothing;end if;end loop;end if;return private.sect_arts_snapshot(uid,p_channel);exception when invalid_text_representation or numeric_value_out_of_range then raise exception '門派功法資料不正確';end $$;

create or replace function public.player_sect_art_command(p_channel text,p_action text,p_sect text,p_slot integer,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_sect_states;profile private.player_art_profiles;art private.player_sect_arts;c record;skill boolean;learn_limit integer;used integer;cost bigint;w private.player_resource_wallets;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') or p_action not in('learn','upgrade','forget') or p_slot not between 0 and 2 or p_request_id is null then raise exception '門派功法請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id) then raise exception '重複的功法請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-sect-arts-'||p_channel));select * into s from private.player_sect_states where user_id=uid and channel=p_channel for update;select * into profile from private.player_art_profiles where user_id=uid and channel=p_channel for update;select * into c from private.sect_catalog() where name=p_sect;if s.user_id is null or profile.user_id is null or c.name is null then raise exception '伺服器門派狀態尚未建立';end if;skill:=private.sect_slot_is_skill(c.name,p_slot);select * into art from private.player_sect_arts where user_id=uid and channel=p_channel and sect_name=c.name and slot=p_slot for update;if p_action='learn' then if s.sect_name<>c.name then raise exception '只能在目前門派學習傳承';end if;learn_limit:=case when s.sect_rank>=2 then 3 when s.sect_rank>=1 then 2 else 1 end;if p_slot>=learn_limit then raise exception '目前門派職位不足';end if;if art.user_id is not null then raise exception '此門派傳承已習得';end if;if not skill then select count(*) into used from private.player_sect_arts a where a.user_id=uid and a.channel=p_channel and not private.sect_slot_is_skill(a.sect_name,a.slot);if used>=profile.arts_capacity then raise exception '門派功法格已滿';end if;end if;insert into private.player_sect_arts(user_id,channel,sect_name,sect_star,slot) values(uid,p_channel,c.name,c.star,p_slot);elsif p_action='upgrade' then if art.user_id is null or skill then raise exception '此傳承無法升級';end if;if art.level>=10 then raise exception '功法已達滿級';end if;cost:=round(500*c.star*c.star*power(1.5,art.level-1));select * into w from private.player_resource_wallets where user_id=uid and channel=p_channel for update;if w.user_id is null or w.aura<cost then raise exception '靈氣不足';end if;update private.player_resource_wallets set aura=aura-cost,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into w;update private.player_sect_arts set level=level+1 where user_id=uid and channel=p_channel and sect_name=c.name and slot=p_slot;else if art.user_id is null then raise exception '尚未習得此傳承';end if;delete from private.player_sect_arts where user_id=uid and channel=p_channel and sect_name=c.name and slot=p_slot;end if;update private.player_art_profiles set revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into profile;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload) values(uid,p_channel,profile.revision,'sect_art_'||p_action,p_request_id,jsonb_build_object('sect',c.name,'slot',p_slot,'cost',coalesce(cost,0)));return jsonb_build_object('arts',private.sect_arts_snapshot(uid,p_channel),'wallet',case when w.user_id is null then null else private.wallet_snapshot(w) end);end $$;

create or replace function public.player_arts_expand(p_channel text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());profile private.player_art_profiles;w private.player_resource_wallets;cost bigint;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') or p_request_id is null then raise exception '擴充請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id) then raise exception '重複的擴充請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-sect-arts-'||p_channel));select * into profile from private.player_art_profiles where user_id=uid and channel=p_channel for update;select * into w from private.player_resource_wallets where user_id=uid and channel=p_channel for update;if profile.user_id is null or w.user_id is null then raise exception '伺服器功法狀態尚未建立';end if;if profile.arts_capacity>=40 then raise exception '功法格已達上限';end if;cost:=round(1000*power(1.28,profile.arts_capacity-8));if w.spirit_stone<cost then raise exception '靈石不足';end if;update private.player_resource_wallets set spirit_stone=spirit_stone-cost,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into w;update private.player_art_profiles set arts_capacity=arts_capacity+1,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into profile;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload) values(uid,p_channel,profile.revision,'arts_capacity_expanded',p_request_id,jsonb_build_object('capacity',profile.arts_capacity,'cost',cost));return jsonb_build_object('arts',private.sect_arts_snapshot(uid,p_channel),'wallet',private.wallet_snapshot(w));end $$;

revoke all on function private.sect_slot_is_skill(text,integer),private.sect_arts_snapshot(uuid,text) from public,anon,authenticated;
revoke execute on function public.player_sect_arts_bootstrap(text,jsonb,integer),public.player_sect_art_command(text,text,text,integer,uuid),public.player_arts_expand(text,uuid) from public,anon;
grant execute on function public.player_sect_arts_bootstrap(text,jsonb,integer),public.player_sect_art_command(text,text,text,integer,uuid),public.player_arts_expand(text,uuid) to authenticated;
